        body: `文章題は、頭の中だけで考えると数量の関係がこんがらがってしまいます。そこで、量を線の長さに置きかえて図にする「線分図」を使うと、関係が一目で分かるようになります。

■ 線分図の基本ルール
・量が大きいほど線を長くかく（長さ＝量）
・「全体」を表す線分に区切り線を入れて「部分」を表す
・わからない量は「□」や「①」として線の上に書きこんでよい

■ 例題
全部で250ページの本を、1日目に90ページ読んだ。残りは何ページか。

【線分図の描き方】
①全体250ページを1本の線分で表す
②左端から90ページのところに区切り線を入れる（読んだ部分）
③区切り線から右端までが「残り」

　解：残り＝250－90＝160ページ

■ 3つ以上の量をつなげる
「A、B、Cの合計は540円」のような問題では、A・B・Cの線分を横一列につなげて1本の長い線分（＝合計540円）として表すと、それぞれの区切りの位置から関係がつかみやすくなります。`,
