        body: `■ 線の長さが量そのもの
250 ページを 1 本の線にすると、読んだ 90 は左の区切りまで、残り 160 は右側の長さ。**足し算・引き算が「長さの足し引き」になる**ので、何が全体で何が部分かを取りちがえません。2 日目が 1 日目より 15 多い（105）なら、区切りをもう 1 つ入れて 250 − 90 − 105 ＝ **55 ページ**。ひっかけの 195 は「読んだ合計」で、残りの区切りの右側ではありません。

■ 「残りの 1/3」は残りの線に対して
300 ページの 2/5（120）を読むと、残りの線は 180。「残りの 1/3」は**この 180 の線を 3 等分した 1 つ ＝ 60**。まだ読んでいないのは 180 − 60 ＝ **120 ページ**。ひっかけの 80 は 2/5 ＋ 1/3 ＝ 11/15 と、**もとにする量のちがう分数を足した**もの。線分図では「残りの線」の上に区切りを入れるので、全体の 1/3（100）ではないことが目で分かります。

■ 描く手順
①全体を 1 本 ②左から順に区切り（読んだ分）③区切りの右が残り ④「残りの〜分の 1」は残りの線を等分 ⑤分からない量は □ や ① と書く。

★ ここがポイント：線分図は**長さ ＝ 量**なので、全体 − 部分 が「区切りの右側の長さ」になる（250 − 90 − 105 ＝ 55）。**「残りの 1/3」は残りの線（180）を等分した 60**で、全体の 1/3 でも、2/5 ＋ 1/3 でもない（120 ページ）。`,
