        body: `2つの数の「和」と「差」がわかっているとき、線分図をそろえて描くと、大きい方・小さい方をそれぞれ求める公式が見えてきます。

■ 線分図から公式を導く
小さい方の線分に、差の分だけ足すと大きい方の線分になる。
2本をならべて2倍すると考えると、
　大きい方×2＝和＋差 → 大きい方＝（和＋差）÷2
　小さい方×2＝和－差 → 小さい方＝（和－差）÷2

■ 例題
姉と妹の合計金額は3,600円で、姉は妹より600円多い。それぞれいくらか。

　姉（大きい方）＝（3,600＋600）÷2＝2,100円
　妹（小さい方）＝（3,600－600）÷2＝1,500円
　確認：2,100＋1,500＝3,600円、2,100－1,500＝600円`,
