        body: `■ 小さいほうに差を足すと、大きいほうが 2 本になる
姉と妹の合計 3,600 円、姉が 600 円多い。線分図で妹の線に差 600 を足すと、姉の線と同じ長さになります。和 3,600 に差 600 を足した 4,200 は、**姉の線が 2 本ぶん**。だから姉 ＝ 4,200÷2 ＝ **2,100 円**。逆に、姉の線から差を切り取ると妹の線が 2 本ぶん：3,600 − 600 ＝ 3,000 → 妹 ＝ **1,500 円**。**「足せば大きいほう 2 本、引けば小さいほう 2 本」**が公式の正体です。

■ ひっかけの読み方
弟 18 才（和 32・差 4）は (32 ＋ 4)÷2 で、**大きいほう（兄）の式を弟に使った**もの。弟は (32 − 4)÷2 ＝ **14 才**。「54」は 48 ＋ 6 で止めた数で、**2 本ぶんを 1 本に戻す ÷2 を忘れた**もの（大きいほう 27）。

■ 求めた片方から、もう片方を出してもよい
姉 2,100 が出たら妹 ＝ 3,600 − 2,100 ＝ 1,500（和から引く）でも、2,100 − 600 ＝ 1,500（差を引く）でも同じ。**2 通りで一致すれば公式の ＋− を取りちがえていない**。

■ 手順
①どちらが大きいか文で決める ②大きいほう ＝ (和 ＋ 差)÷2 ③小さいほう ＝ 和 − 大きいほう（または (和 − 差)÷2）④和と差の両方に戻す。

★ ここがポイント：和に差を**足すと大きいほうが 2 本ぶん**、**引くと小さいほうが 2 本ぶん**になるから ÷2（姉 (3,600 ＋ 600)÷2 ＝ 2,100、妹 (3,600 − 600)÷2 ＝ 1,500）。大きい・小さいの取りちがえ（弟 18）と ÷2 の忘れ（54）に注意。`,
