        body: `□を含む式を解くときは、「最後に行われた計算」から順番に逆算していきます。逆算では、演算をそれぞれ反対の演算に置きかえます。

■ 逆演算の対応表
　＋（たす）　⇄　－（ひく）
　－（ひく）　⇄　＋（たす）
　×（かける）⇄　÷（わる）
　÷（わる）　⇄　×（かける）

■ 例題
3×□－8＝25 を解け。

【手順（最後の計算から逆にたどる）】
①式の最後に行われているのは「－8」なので、まずこれを逆にする：25＋8＝33
②次に「×3」を逆にする：33÷3＝11

　□＝11
　確認：3×11－8＝33－8＝25 で合っている`,
