        body: `■ 式は「□ に操作を順にかけた結果」
3×□ − 8 ＝ 25 は、□ を「3 倍して」「8 引いて」25 になった、という順番。もとに戻すには**後にした操作から反対の操作で外す**：まず「8 引く」の反対「8 足す」で 25 ＋ 8 ＝ 33（これが 3×□）、次に「3 倍」の反対「3 でわる」で 33÷3 ＝ **11**。結び目を後から結んだ順にほどくのと同じです。

■ 反対の計算にする理由
8 を引いた結果が 25 なら、引く前は 8 大きい。3 倍した結果が 33 なら、3 倍する前は 3 分の 1。**「した操作の反対」で 1 段ずつ前の値に戻る**。ひっかけの 3（□÷4 ＋ 7 ＝ 19）は、「÷4」をそのまま「12÷4」としたもので、反対の「×4」で 12×4 ＝ **48**。

■ かっこは 1 かたまり
(□ ＋ 5)×3 ＝ 27 は「□ に 5 足して」「3 倍」。最後は ×3 なので 27÷3 ＝ 9 が (□ ＋ 5)、□ ＝ **4**。ひっかけの 12 は、かっこを無視して 5×3 を先に計算したもの。**かっこの中は 1 つの数として、外側の操作から外す**。

■ 手順
①□ に対して「何をどの順にしたか」を書き出す ②最後の操作から、反対の操作で 1 段ずつ戻す ③□ が出たらもとの式に入れて確かめる。

★ ここがポイント：式は □ に**操作を順にかけた結果**なので、**最後の操作から反対の操作で外す**（25 ＋ 8 ＝ 33、33÷3 ＝ 11）。÷ の反対は ×（12×4 ＝ 48、12÷4 ＝ 3 は誤り）。**かっこは 1 かたまり**として外側から（27÷3 ＝ 9 → □ ＝ 4）。`,
