        body: `■ 「妹の 2 倍より 150 多い」は、妹を①にすると描ける
姉は「妹の 2 倍」に 150 を足した長さ。妹を①にすると姉は ② ＋ 150 で、線分図は妹 1 マス、姉 2 マス ＋ はみ出し 150。合計 1,500 は **③ ＋ 150**。**はみ出しの 150 を先に取り除く**と ③ ＝ 1,350、① ＝ **450 円**（妹）、姉 ＝ 900 ＋ 150 ＝ 1,050 円。

■ 「少ない」なら取り除くのではなく足す
「兄は弟の 3 倍より 200 円少ない」なら兄 ＝ ③ − 200。合計 2,400 ＝ ④ − 200 なので、**へこみの 200 を足し戻して** ④ ＝ 2,600、① ＝ **650 円**。ひっかけの 550 は「多い」と読んで ④ ＋ 200 ＝ 2,400 としたもの。**多い → はみ出し（引く）、少ない → へこみ（足す）**。

■ 基準を逆にしない
「兄は弟の 3 倍より 200 多い」で兄を①にすると、弟は「兄の 3 分の 1 より…」となって描けません。**「〜の □ 倍」の「〜」（倍の相手）を①にする**。弟①、兄 ③ ＋ 200、合計 ④ ＋ 200 ＝ 2,000 → ① ＝ 450、兄 ＝ **1,550 円**。ひっかけの 450 は弟の額。

■ 手順
①「〜の □ 倍」の「〜」を①に ②もう一方を □ ± △ で描く ③合計 ＝ マスの合計 ± △ → △ を先に処理 ④① を出し、両方に戻す ⑤合計と「□ 倍より △」の両方で検算。

★ ここがポイント：**「〜の □ 倍」の「〜」を①**にして、もう一方を「□ マス ± はみ出し」で描く（姉 ＝ ② ＋ 150）。合計から**はみ出しを先に取り除く**（1,500 − 150 ＝ ③ → 450 円）。「少ない」ならへこみを足し戻す（2,400 ＋ 200 ＝ ④ → 650 円）。`,
