        body: `品物が3種類以上あるつるかめ算は、そのままでは解けません。まず「個数がわかっている（またはわかりやすい）1種類」を全体から除いて、残りを普通の2種類のつるかめ算として解きます。

■ 例題
60円、90円、150円の3種類のお菓子を合わせて25個買って、代金の合計は2,400円だった。150円のお菓子を5個買ったとすると、60円と90円のお菓子はそれぞれ何個か。

【手順】
①150円の分を先に除く：150×5＝750円、個数5個
②残り：個数25－5＝20個、代金2,400－750＝1,650円
③60円と90円の2種類のつるかめ算で解く
　全部60円だったら：60×20＝1,200円
　実際との差：1,650－1,200＝450円
　1個を60円→90円に変えるごとに30円ずつ増えるので、90円の個数＝450÷30＝15個
　60円の個数＝20－15＝5個

　60円5個、90円15個、150円5個（確認：60×5＋90×15＋150×5＝300＋1,350＋750＝2,400円）`,
