        body: `■ 個数が分かっている種類は「取り分けて」しまう
150 円のお菓子は 5 個と分かっているので、その 5 個・750 円を全体から取り除きます。残りは 20 個・1,650 円で、**60 円と 90 円の 2 種類だけ**——ふつうのつるかめ算です。全部 60 円なら 1,200 円、差 450 円、1 個入れかえで 30 円増えるので 90 円は 450÷30 ＝ **15 個**、60 円は **5 個**。

■ 除かないひっかけ
25 個・2,400 円のまま 60 円と 90 円で解くと、全部 60 円 1,500 円、差 900 円、900÷30 ＝ 30 個となり、**25 個を超えてしまいます**（150 円の分が混ざっているから）。3 種類のままでは 2 種類の入れかえで説明できません。

■ 「全部 90 円なら」で出るのは 60 円の個数
全部 90 円なら 1,800 円、実際より 150 円多い。1 個を 60 円に変えるごとに 30 円減るので 150÷30 ＝ 5 個——これは **60 円の個数**（仮定しなかったほう）。ひっかけの「90 円が 5 個」は逆。

■ 最後に戻す
答えは 60 円 5 個・90 円 15 個・150 円 5 個で、**個数 25、代金 2,400** に戻るか確かめます。除いた分を忘れると個数が 20 で止まります。

■ 手順
①個数の分かっている種類 × 値段 ＝ 除く代金 ②残りの個数・代金 ③2 種類のつるかめ算 ④除いた分を足し戻して個数と代金の両方で検算。

★ ここがポイント：3 種類は**個数の分かっている 1 種類（150 円 5 個・750 円）を先に取り除く**と、残り 20 個・1,650 円の 2 種類つるかめ算（450÷30 ＝ 15 → 90 円 15 個、仮定しなかったほう）。除かずに解くと 30 個で 25 を超える。最後に**除いた分を戻して 25 個・2,400 円**に戻す。`,
