        body: `■ 途中で決めると「候補が 2 つ」のまま
和 11・十の位が大きい → 92・83・74・65。偶数 → 92・74。ここで「大きいほう」と決めた 92 は、最後のヒント「十の位は 8 より小さい」を使っていません。**ヒントが残っているうちは候補が 1 つになっていない**ので、使い切るまで進めます → **74**。ヒントが余ったら、それは検算用。

■ 順番はどれからでもよい
「偶数」から始めれば一の位が 2・4・6・8、和 11 で十の位は 9・7・5・3、十の位が大きいのは 92・74、8 より小さいのは 74。**どの順でも同じ 74 に着く**のが正しい答えの印。

■ 数字を入れかえると 27 大きくなる
2 けたの数の十の位と一の位を入れかえると、差は**「2 つの数字の差 × 9」**になります（36 と 63 の差 27 ＝ (6 − 3)×9。十の位の数字が 1 減って一の位が 1 増えると、10 減って 1 増えるので 9 ずつ変わるから）。27 大きいなら数字の差は 27÷9 ＝ 3。和が 9 で差が 3 なので和差算で 6 と 3。入れかえて大きくなるのは一の位のほうが大きい数なので、もとの数は **36**（入れかえると 63）。ひっかけの 63 は入れかえたあとの数。**「もとの数」と「入れかえた数」のどちらを聞かれたか**。

■ 手順
①最初のヒントで候補を全部書く ②ヒントを 1 つずつ使ってしぼる ③候補が 1 つになるまで続け、余ったヒントで検算 ④入れかえの問題は「差 ＝ 9 × (数字の差)」を使う ⑤答えを全ヒントに照らす。

★ ここがポイント：**ヒントを使い切るまで候補は 1 つにならない**（92・74 → 8 より小さい → 74）。どの順で使っても同じ答えになる。入れかえの差は**9 × (数字の差)**（27 → 差 3、和 9 → 3 と 6 → もとの数 36、63 は入れかえたほう）。`,
