        body: `■ 同じ道のりなら 速さ × 時間 が一定
道のりが同じとき、速さが 6/5 倍（60 → 72）になれば、時間は 5/6 倍。**速さの比 5:6 ↔ 時間の比 6:5（逆比）**。予定の時間を 6、実際を 5 とすると、差の 1 が「4 分早い」に当たるので、予定 ＝ 4×6 ＝ 24 分、実際 20 分。道のり ＝ 60×24 ＝ **1,440m**（72×20 ＝ 1,440 で一致）。**道のりが書かれていなくても、比の差と 4 分を結びつければ**時間が決まり、道のりも出ます。

■ 「速さの差 × 早くなった時間」は意味がない
ひっかけの 12×4 ＝ 48m は、速さの差（m/分）と時間（分）をかけたもの。これは「差の速さで 4 分進んだ道のり」で、家から駅の道のりとは関係ありません。**道のり ＝ 速さ × その速さで進んだ時間**（同じ組で）。

■ 2 割速い → 時間は 2 割減ではない
速さ 1.2 倍なら時間は 1÷1.2 ＝ 5/6 倍。30 分なら 30×5/6 ＝ **25 分**（ひっかけの 24 分は 0.8 倍）。**逆比は「1 ÷ 倍率」**で、1 − 0.2 ではありません。速さ × 時間 ＝ 一定 で確かめる：60×30 ＝ 72×25 ＝ 1,800 ✓、72×24 ＝ 1,728 ✗。

■ 手順
①実際の速さ ＝ 予定 × (1 ＋ 割合) ②速さの比 → 時間の比（逆）③時間の比の差 ＝ 早く（遅く）着いた分 → 比の 1 あたりの時間 ④予定の時間 → 道のり ＝ 速さ × 時間 ⑤実際の組でも同じ道のりか。

★ ここがポイント：同じ道のりでは**速さの比の逆が時間の比**（5:6 → 6:5）で、**比の差 1 ＝ 4 分**から予定 24 分、道のり 60×24 ＝ 1,440m。速さの差 × 時間（48m）は意味がない。**2 割速いと時間は 5/6 倍**（30 → 25 分、0.8 倍の 24 は誤り）。`,
